cat > "$BB_THREAD_STORAGE/audit.py" <<'EOF'
# /// script
# requires-python = ">=3.11"
# dependencies = ["pyyaml"]
# ///
import re, sys, yaml
from pathlib import Path
ORDER = ["type","title","description","resource","tags","status","generated","verified","sources"]
SRC = ["id","resource","title","author"]
for f in sorted(Path("bundle").rglob("*.md")) + sorted(Path("sources/evaluate").glob("*.md")):
    if f.name in ("index.md","log.md"): continue
    t = f.read_text()
    m = re.match(r"\A---\n(.*?)\n---\n", t, re.S)
    if not m: print(f, "NO FM"); continue
    fm = yaml.safe_load(m[1]); keys = list(fm)
    known = [k for k in keys if k in ORDER]
    if known != sorted(known, key=ORDER.index): print(f, "FIELD ORDER", keys)
    extra = [k for k in keys if k not in ORDER]
    if extra: print(f, "EXTRA", extra)
    for s in fm.get("sources") or []:
        k = [x for x in s if x in SRC]
        if k != sorted(k, key=SRC.index) or set(s) - set(SRC): print(f, "SOURCE ORDER", list(s))
    if not re.search(r"^generated: \{ by: .+, at: .+ \}$", m[1], re.M): print(f, "GENERATED NOT INLINE")
    if fm.get("status") != "draft" and "verified" not in fm: print(f, "STATUS", fm.get("status"), "no verified")
    if "verified" in fm: print(f, "VERIFIED", fm["verified"])
    body = t[m.end():]
    h1 = re.findall(r"^# (.+)$", re.sub(r"^```.*?^```", "", body, flags=re.M|re.S), re.M)
    if h1 != [fm.get("title")]: print(f, "H1/title", h1, "|", fm.get("title"))
EOF
